\section{Introduction}

The splitting of rational primes in number fields is one of the oldest themes of algebraic number theory, and cyclotomic fields are its best-understood laboratory. In $\Q(\zeta_n)$ a prime $p\nmid n$ splits into $\varphi(n)/t$ primes of residue degree $t$, where $t$ is the multiplicative order of $p$ modulo $n$. Cyclotomic rings are also the arithmetic substrate of much of modern lattice-based cryptography, where the factorization of $\Phi_n$ modulo a prime governs the Chinese-remainder (number-theoretic transform) decomposition of the ring.

We adopt an information-theoretic viewpoint. Treat a random unramified prime as a random Frobenius class, uniformly distributed over the Galois group (the content of the Chebotarev density theorem, or for cyclotomic fields, Dirichlet's theorem). Then the residue of $p$ and its splitting type become two random variables on a finite probability space, and one can ask how many bits of the splitting type the residue reveals. We call this the \emph{type channel}.

Computations for abelian fields of degrees $2,3,4,5,6,8,9$ --- real subfields of cyclotomic fields and full cyclotomic fields --- found in every case that the residue reveals \emph{all} of the type: the mutual information equals the type entropy. We call this \emph{full pinning}. This paper treats the tenth rung, $\Q(\zeta_{11})$, proves full pinning for all abelian fields at once, derives the exact degree-ten constants, and settles several numerical questions raised by the experimental record.

\subsection{Experimental background}
The following predictions for $\Q(\zeta_{11})$ were made in advance and checked on data:
\begin{enumerate}
\item $T(p)=\ord_{11}(p)\in\{1,2,5,10\}$ with densities $\{1/10,1/10,4/10,4/10\}$, observed on $295{,}946$ unramified primes.
\item $I(p\bmod 11;T)=H(T)\approx 1.7219$ bits, with the type degenerate on each residue class.
\item On $400$ primes the factor-degree pattern of $\Phi_{11}\bmod p$ was $[1^{10}]$, $[2^5]$, $[5,5]$ or $[10]$ according as $\ord_{11}(p)=1,2,5,10$.
\item For semiprimes, $I(N\bmod 11;\text{type pair})$ was measured at $1.2002$, against an enumeration value $1.1999$ and an earlier closed-form prediction $1.2027$.
\end{enumerate}
We prove items 1--3 exactly (item 3 for all primes and all conductors) and resolve item 4: the exact law is $1.20271\ldots$, within $3\cdot10^{-5}$ of the closed-form prediction and strictly above the other two figures, which are finite-sample estimates.

\subsection{Summary of results}
\begin{itemize}
\item \textbf{Cyclic Chebotarev densities} (Theorem~\ref{thm:cyclic}): every cyclic field of degree $n$ has type densities $\varphi(d)/n$ and the closed-form type entropy above.
\item \textbf{Abelian full pinning} (Theorem~\ref{thm:abelian}): $I(c;T)=H(T)$, $H(T\mid c)=0$, $\ltwo|A|-I(c;T)=H(c\mid T)$ for every finite abelian $A$, injective $c$ and any $T$.
\item \textbf{Degree ten} (Theorem~\ref{thm:deg10}): $I=H(T)=\ltwo5-\frac35$, $H(p\bmod 11\mid T)=\frac85$.
\item \textbf{Factor patterns} (Theorem~\ref{thm:orbit}): $\Phi_n\bmod p$ has pattern $[t^{\varphi(n)/t}]$, the cycle type of multiplication by $p$.
\item \textbf{Tower} (Theorems~\ref{thm:real}, \ref{thm:towerbit}): $H(T^+)=\ltwo5-\frac85$, $H(T\mid T^+)=1$, $H(T)=H_{C_2}+H_{C_5}$.
\item \textbf{Semiprime channel} (Theorem~\ref{thm:semi}): $I_{\mathrm{semi}}=\ltwo5+\frac{12}{25}\ltwo3-\frac{47}{25}$.
\item \textbf{Which-factor wall} (Theorem~\ref{thm:wall}): zero for every swap-invariant residue, hence for every group read through its abelianization.
\item \textbf{Attenuation and certified numerics} (Theorems~\ref{thm:atten}, \ref{thm:cert}).
\end{itemize}

\section{Setting and definitions}

\subsection{Frobenius and splitting types}
Let $K/\Q$ be finite Galois with group $G$ and $p$ unramified in $K$. The Frobenius elements of primes above $p$ form a conjugacy class $\mathrm{Frob}_p\subseteq G$; if it has order $t$, then $p$ is a product of $|G|/t$ distinct primes of $K$, each of residue degree $t$.

\begin{definition}[Frobenius type]
The \emph{Frobenius type} of $p$ in $K$ is $T(p)=$ the order of $\mathrm{Frob}_p$. More generally a \emph{type readout} is any function $T:G\to\tau$.
\end{definition}

For $K=\Q(\zeta_n)$ the Galois group is $(\Z/n)^\times$ via $\sigma_a:\zeta_n\mapsto\zeta_n^a$, and the Frobenius of $p\nmid n$ is $\sigma_p$, i.e.\ the residue class $p\bmod n$. Thus $T(p)=\ord_n(p)$. For the maximal real subfield $K^+=\Q(\zeta_n+\zeta_n^{-1})$ the group is $(\Z/n)^\times/\{\pm1\}$ and $T^+(p)$ is the order of the image of $p$ there. For $n=11$, squaring has kernel exactly $\{\pm1\}$ (indeed $g^2=h^2$ iff $g=\pm h$), so it identifies the quotient with the subgroup of squares and $T^+(p)=\ord_{11}(p^2)$.

\subsection{The uniform-Frobenius model}
\begin{definition}[uniform model]
A \emph{sample} is a finite set $S$ with the uniform measure. For the single-prime channel of an abelian field with group $A$ the sample is $S=A$. For semiprimes $N=pq$ the sample is $A\times A$, the Frobenius classes of $p$ and $q$ being independent and uniform.
\end{definition}
By the Chebotarev density theorem this model describes natural densities of primes exactly.

\begin{definition}[entropy and mutual information]
For a readout $f:S\to\alpha$ put $P(f=a)=|\{w\in S: f(w)=a\}|/|S|$ and $H(f)=-\sum_a P(f=a)\ltwo P(f=a)$. For readouts $f,g$ write $(f,g)$ for the joint readout and set $H(f\mid g)=H(f,g)-H(g)$ and $I(f;g)=H(f)+H(g)-H(f,g)$.
\end{definition}

\begin{definition}[residue readout, full pinning]
A \emph{residue readout} on $G$ is a function $c:G\to\kappa$; for cyclotomic fields $c$ is the residue $p\bmod n$ itself, which is injective. We say $c$ \emph{fully pins} $T$ if $I(c;T)=H(T)$.
\end{definition}
Since $I(c;T)=H(T)-H(T\mid c)$, full pinning is equivalent to \emph{per-class degeneracy} $H(T\mid c)=0$.

\section{Cyclic fields: densities and closed-form type entropy}

\begin{theorem}[Chebotarev densities of a cyclic field]\label{thm:cyclic}
Let $G$ be cyclic of order $n$ and $d\mid n$. Exactly $\varphi(d)$ elements of $G$ have order $d$. Hence in a cyclic field of degree $n$ the type takes value $d$ with density $\varphi(d)/n$, and
\[ H(T)=-\sum_{d\mid n}\frac{\varphi(d)}{n}\ltwo\frac{\varphi(d)}{n}. \]
\end{theorem}
\begin{proof}[Proof sketch]
$G$ has a unique subgroup of order $d$; it is cyclic, and its generators --- $\varphi(d)$ of them --- are exactly the elements of order $d$. All orders divide $n$, so substituting these fibre sizes into the definition of entropy gives the closed form.
\end{proof}

For $n=10$ the divisors $1,2,5,10$ have totients $1,1,4,4$. In $(\Z/11)^\times$: order $1$: $\{1\}$; order $2$: $\{10\}$; order $5$: $\{3,4,5,9\}$; order $10$: $\{2,6,7,8\}$.

\section{The abelian full-pinning law}

\begin{theorem}[abelian full pinning]\label{thm:abelian}
Let $A$ be a finite abelian group, $c:A\to\kappa$ injective and $T:A\to\tau$ arbitrary. In the uniform model on $A$:
\begin{enumerate}
\item $I(c;T)=H(T)$;
\item $H(T\mid c)=0$;
\item $\ltwo|A|-I(c;T)=H(c\mid T)$.
\end{enumerate}
\end{theorem}
\begin{proof}[Proof sketch]
This is the abelian case of a general coset law for a finite group $G$ with derived subgroup $G'$: if $c(a)=c(b)$ iff $ab^{-1}\in G'$, then $c$ sees exactly the image of Frobenius in $G/G'$, and $I(c;T)=H(T)-H(T\mid c)$, $\ltwo|c(G)|-I(c;T)=H(c\mid T)$, with $I(c;T)=H(T)$ whenever $T$ is constant on $G'$-cosets. For abelian $A$, $G'$ is trivial, every injective readout is a coset readout and every $T$ is constant on singleton cosets. Concretely, $T$ factors through $c$, so $(c,T)$ has the same fibres as $c$ and $H(c,T)=H(c)=\ltwo|A|$, which yields all three identities.
\end{proof}

\begin{remark}
In a non-abelian group, a congruence-type residue sees only the image of Frobenius in $G/G'$; conjugacy classes of different orders may share that image, and then $H(T\mid c)>0$. In abelian fields there is no such obstruction: every splitting statistic is a function of the residue. This explains why full pinning succeeded on every abelian rung examined --- degrees $2$--$6$, $8$, $9$, $10$, real subfields and full cyclotomic fields alike.
\end{remark}

\section{Degree ten: exact constants}

Let $A=(\Z/11)^\times$, $c(g)=g$ and $T(g)=\ord(g)$.

\begin{theorem}[type entropy at degree ten]\label{thm:H10}
$H(T)=\ltwo 5-\frac35\approx 1.72193$.
\end{theorem}
\begin{proof}
The distribution is $(1,1,4,4)/10$, so
$H(T)=\frac{2}{10}\ltwo 10+\frac{8}{10}\ltwo\frac{10}{4}=\ltwo10-\frac85=\ltwo5-\frac35$.
\end{proof}

\begin{theorem}[full pinning at degree ten]\label{thm:deg10}
In the uniform-Frobenius model for $\Q(\zeta_{11})$,
\[ I(p\bmod 11;T)=H(T)=\ltwo5-\tfrac35,\qquad H(T\mid p\bmod 11)=0,\qquad H(p\bmod 11\mid T)=\tfrac85. \]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:abelian} gives the first two and $\ltwo10-I=H(c\mid T)$; by Theorem~\ref{thm:H10}, $H(c\mid T)=1+\ltwo5-(\ltwo5-\frac35)=\frac85$.
\end{proof}
Of the $\ltwo10\approx3.3219$ bits in the residue, $1.7219$ determine the type; the remaining $1.6$ distinguish residues of equal type (e.g.\ $3,4,5,9$).

\section{Factor patterns of cyclotomic polynomials}

\begin{theorem}[factor-degree law]\label{thm:factor}
Let $p\nmid n$ be prime and $t=\ord_n(p)$. Every monic irreducible factor of $\Phi_n$ in $\F_p[x]$ has degree $t$; hence the factor-degree multiset is $[t,\dots,t]$ with $\varphi(n)/t$ entries.
\end{theorem}
\begin{proof}[Proof sketch]
$\Phi_n$ is separable over $\F_p$ with roots the primitive $n$-th roots of unity $\eta\in\overline{\F}_p$. Now $\eta\in\F_{p^k}$ iff $n\mid p^k-1$ iff $t\mid k$, so every root has degree $t$ over $\F_p$. Comparing with $\deg\Phi_n=\varphi(n)$ counts the factors.
\end{proof}

\begin{lemma}[group-side mirror]\label{lem:mirror}
For $g$ in a finite group $G$, the permutation $x\mapsto gx$ has all cycles of length $\ord(g)$, and $[G:\langle g\rangle]$ of them.
\end{lemma}
\begin{proof}[Proof sketch]
The cycles are the cosets $\langle g\rangle x$.
\end{proof}

\begin{theorem}[factor pattern equals orbit pattern]\label{thm:orbit}
For $p\nmid n$, the factor-degree multiset of $\Phi_n$ over $\F_p$ equals the cycle type of multiplication by $p\bmod n$ on $(\Z/n)^\times$.
\end{theorem}

\begin{corollary}[polynomial-level full pinning]
If $p,q\nmid n$ are primes with $p\equiv q\pmod n$, then $\Phi_n$ has the same factor-degree pattern over $\F_p$ and over $\F_q$.
\end{corollary}

\begin{corollary}[the four degree-ten patterns]
For every prime $p\neq 11$ the pattern of $\Phi_{11}$ over $\F_p$ is $[1^{10}]$, $[2^5]$, $[5,5]$ or $[10]$ according as $\ord_{11}(p)=1,2,5,10$, and it is determined by $p\bmod 11$. Witnesses: $p=23$ gives $[1^{10}]$, $p=43$ gives $[2^5]$, $p=3$ gives $[5,5]$, and $p=2$ (a primitive root mod $11$) gives $[10]$, so $\Phi_{11}$ is irreducible over $\F_2$.
\end{corollary}

\begin{remark}
In the original 400-prime check, a first comparison reported $400/400$ mismatches while every pattern was correct: the predicted pattern was wrapped in one more layer of tuple than the computed one. Another pitfall is indexing a lookup by residue instead of by type. Theorem~\ref{thm:orbit} makes the comparison canonical: both sides are multisets of positive integers summing to $\varphi(n)$.
\end{remark}

\section{The tower $\Q\subset\Q(\zeta_{11})^+\subset\Q(\zeta_{11})$}

\begin{lemma}[additivity for independent readouts]\label{lem:prod}
For nonempty finite samples $S_1,S_2$ and readouts $f,g$, the readout $(x,y)\mapsto(f(x),g(y))$ on $S_1\times S_2$ has entropy $H(f)+H(g)$.
\end{lemma}
\begin{proof}[Proof sketch]
Fibres are products of fibres, so probabilities multiply.
\end{proof}

We have $(\Z/11)^\times\cong C_2\times C_5$ with $C_2=\{\pm1\}$ and $C_5=\{1,3,4,5,9\}$ the squares. The order of an element is the product of the orders of its components, and the product map is injective on $\{1,2\}\times\{1,5\}$.

\begin{theorem}[CRT additivity at degree ten]\label{thm:crt}
$H(T)=H_{C_2}(\ord)+H_{C_5}(\ord)$ with $H_{C_2}(\ord)=1$ and $H_{C_5}(\ord)=\ltwo5-\frac85$.
\end{theorem}
\begin{proof}[Proof sketch]
Transport along $C_{10}\cong C_2\times C_5$; by injectivity $T$ carries the same information as the pair of component orders; apply Lemma~\ref{lem:prod}. In $C_5$ the orders $1,5$ have probabilities $1/5,4/5$.
\end{proof}

\begin{theorem}[real subfield]\label{thm:real}
In $\Q(\zeta_{11})^+$, $T^+=1$ on $\{\pm1\}$ and $T^+=5$ elsewhere, so $H(T^+)=\ltwo5-\frac85\approx0.72193$, and $I(p\bmod 11;T^+)=H(T^+)$.
\end{theorem}

\begin{theorem}[the tower bit]\label{thm:towerbit}
$H(T\mid T^+)=1=\ltwo[\Q(\zeta_{11}):\Q(\zeta_{11})^+]$; equivalently $H(T)=1+H(T^+)$, and $H(T^+)=H_{C_5}(\ord)$.
\end{theorem}
\begin{proof}
$(T^+,T)$ takes values $(1,1),(1,2),(5,5),(5,10)$ with counts $1,1,4,4$, so $H(T^+,T)=H(T)$ and $H(T\mid T^+)=(\ltwo5-\frac35)-(\ltwo5-\frac85)=1$.
\end{proof}

\section{The semiprime channel}

Let $N=pq$ with independent uniform Frobenius classes $(g,h)\in A\times A$, so $N\bmod 11=gh$. Define $\nu(g,h)=gh$, $\pi(g,h)=\{T(g),T(h)\}$ (unordered) and $\omega(g,h)=(T(g),T(h))$ (ordered).

\begin{theorem}[semiprime channel]\label{thm:semi}
\[ I\bigl(N\bmod 11;\{T(p),T(q)\}\bigr)=\ltwo5+\tfrac{12}{25}\ltwo3-\tfrac{47}{25}\approx1.2027101. \]
\end{theorem}
\begin{proof}[Proof sketch]
On the $100$-point sample: $\nu$ is uniform on $10$ values, $H(\nu)=1+\ltwo5$. The ten unordered values $\{1,1\},\{1,2\},\{1,5\},\{1,10\},\{2,2\},\{2,5\},\{2,10\},\{5,5\},\{5,10\},\{10,10\}$ have counts $1,2,8,8,1,8,8,16,32,16$, so $H(\pi)=2\ltwo5-\frac{93}{50}$. The joint readout has $34$ cells: $\nu=1$ splits as $\{1,1\}{:}1$, $\{2,2\}{:}1$, $\{5,5\}{:}4$, $\{10,10\}{:}4$; $\nu=10$ as $\{1,2\}{:}2$, $\{5,10\}{:}8$; each $\nu\in\{3,4,5,9\}$ as $\{1,5\}{:}2$, $\{2,10\}{:}2$, $\{5,5\}{:}3$, $\{10,10\}{:}3$; each $\nu\in\{2,6,7,8\}$ as $\{1,10\}{:}2$, $\{2,5\}{:}2$, $\{5,10\}{:}6$. Hence $H(\nu,\pi)=2\ltwo5+\frac{51}{50}-\frac{12}{25}\ltwo3$ and $I=H(\nu)+H(\pi)-H(\nu,\pi)$.
\end{proof}

\begin{theorem}[ordered channel]\label{thm:ordered}
$H(\omega)=2\ltwo5-\frac65=2H(T)$, $H(\nu,\omega)=2\ltwo5+\frac{42}{25}-\frac{12}{25}\ltwo3$, and $I(\nu;\omega)=I(\nu;\pi)$: the which-factor wall vanishes at degree ten.
\end{theorem}

\section{The which-factor wall vanishes structurally}

\begin{lemma}[average surprisal]
$H(f)=\frac{1}{|S|}\sum_{w\in S}-\ltwo P(f=f(w))$.
\end{lemma}

For a pair $o=(o_1,o_2)$ in a linearly ordered set write $\sym(o)=(\min,\max)$; then $\sym(o)=\sym(o')$ iff $o'=o$ or $o'=o^{\mathrm{swap}}$.

\begin{lemma}[swap-symmetric pairs]\label{lem:swap}
Let $\sigma$ be an involution of $S$, $Y$ a readout with $Y\circ\sigma=Y$ and $O=(O_1,O_2)$ with $O\circ\sigma=O^{\mathrm{swap}}$. Then $H(Y,O)=H(Y,\sym O)+P(O_1\neq O_2)$.
\end{lemma}
\begin{proof}[Proof sketch]
Pointwise: if $O_1(w)=O_2(w)$ the two fibres through $w$ coincide; otherwise the $(Y,\sym O)$-fibre is the disjoint union of the $(Y,O)$-fibres through $w$ and $\sigma(w)$, which $\sigma$ puts in bijection, so the surprisal drops by exactly one bit. Average.
\end{proof}

\begin{theorem}[which-factor wall]\label{thm:wall}
Let $G$ be a group, $S\subseteq G$ finite, $c$ a readout with $c(gh)=c(hg)$ for $g,h\in S$, and $T$ a type readout into a linearly ordered set. On $S\times S$,
$I(c(gh);(Tg,Th))=I(c(gh);\{Tg,Th\})$.
\end{theorem}
\begin{proof}
With $\sigma(g,h)=(h,g)$, apply Lemma~\ref{lem:swap} with $Y=c(gh)$ and with $Y$ constant; both corrections equal $P(Tg\neq Th)$ and cancel in $I=H(Y)+H(O)-H(Y,O)$.
\end{proof}

\begin{corollary}[abelianization]
For any finite group $G$ and any coset readout $c$ of the derived subgroup $G'$, the which-factor wall vanishes for every type readout; in particular for every finite abelian group and every readout.
\end{corollary}
\begin{proof}
$(gh)(hg)^{-1}=[g,h]\in G'$, so $c(gh)=c(hg)$.
\end{proof}

Applied to $(\Z/11)^\times$ this re-derives Theorem~\ref{thm:ordered} without a cell count; applied to $D_4$ and $A_4$ with their abelianization readouts, it explains why previously computed which-factor walls for these non-abelian groups were exactly zero.

\begin{remark}
The reported ``wall'' of $0.0005$ was the difference between two estimates ($1.2002$ measured, $1.1999$ enumerated) of the same quantity; the genuine wall is identically zero.
\end{remark}

\section{Attenuation and certified numerics}

\begin{theorem}[semiprime attenuation]\label{thm:atten}
$H(T)-I(N\bmod 11;\{T(p),T(q)\})=\frac{32}{25}-\frac{12}{25}\ltwo3\approx0.51922>0$.
\end{theorem}

\begin{lemma}[enclosures from integer powers]
For positive integers $a,m,n$: $2^m<a^n$ implies $m/n<\ltwo a$, and $a^n<2^m$ implies $\ltwo a<m/n$. The exact inequalities $2^{23219}<5^{10000}$, $5^{100000}<2^{232193}$, $2^{158496}<3^{100000}$, $3^{100000}<2^{158497}$ give $2.3219<\ltwo5<2.32193$ and $1.58496<\ltwo3<1.58497$.
\end{lemma}

\begin{theorem}[certified values]\label{thm:cert}
$1.7219<I(p\bmod 11;T)<1.72193$, and $1.20268<I_{\mathrm{semi}}<1.20272$; hence $|I_{\mathrm{semi}}-1.2027|<3\cdot10^{-5}$ and $I_{\mathrm{semi}}>1.2002>1.1999$.
\end{theorem}
\begin{proof}
Insert the enclosures into the closed forms, which are linear in $\ltwo5,\ltwo3$.
\end{proof}

\section{Algorithms}

\begin{algorithm}[exact type channel]
Tabulate fibre counts of $c$, $T$ and $(c,T)$ on the group and compute entropies from counts: $O(|G|)$ after evaluating readouts, and $O(|G|^2)$ for the semiprime sample.
\end{algorithm}

\begin{algorithm}[distinct-degree factor pattern]
Set $f=\Phi_n\bmod p$, $h=x$. For $d=1,2,\dots$: $h\leftarrow h^p\bmod f$; $g=\gcd(f,h-x)$; record $\deg g/d$ factors of degree $d$; $f\leftarrow f/g$; stop when $2d>\deg f$, recording a non-constant remainder as one factor. This computes the pattern independently of $\ord_n(p)$.
\end{algorithm}

\begin{algorithm}[certified logarithm enclosure]
Compare the exact integers $2^m$ with $a^n$ and $a^{n'}$ with $2^{m'}$.
\end{algorithm}

\section{Discussion}

Every prediction made in advance for $\Q(\zeta_{11})$ is now a theorem in the uniform-Frobenius model; the factor-pattern check is upgraded to all primes and conductors; the semiprime law is corrected to $1.20271$; the which-factor wall vanishes structurally. Theorem~\ref{thm:abelian} shows full pinning is not a coincidence: for an abelian field the residue \emph{is} the Frobenius, so the informative quantity is the loss $H(c\mid T)=\ltwo|A|-H(T)$, which is $8/5$ bits at degree ten.

For cyclotomic rings in lattice cryptography, Theorem~\ref{thm:orbit} says $\F_p[x]/\Phi_n$ decomposes into $\varphi(n)/t$ copies of $\F_{p^t}$, determined by $p\bmod n$. The semiprime results show that a residue of $N=pq$ reveals strictly less about the factors' splitting than a residue of a single prime --- exactly $0.519$ bits less at degree ten.

All statements concern the uniform-Frobenius model; finite-sample figures deviate by sampling error. A further reported statistic (a projection value $0.0586$ for an ``$\mathrm{Is}(10)$'' construction) is not treated, since its definition could not be reconstructed unambiguously.

\section{Future work}

\begin{conjecture}[2-adic tower gap]
For an odd prime $p$, $H(T)-H(T^+)=2^{1-v_2(p-1)}$ for $\Q(\zeta_p)$ and its maximal real subfield.
\end{conjecture}
\begin{conjecture}[CRT additivity]
For coprime $m,n$, $H_{C_{mn}}(\ord)=H_{C_m}(\ord)+H_{C_n}(\ord)$, failing strictly for non-coprime pairs (losses $0.75$ and $0.816$ bits observed for $(2,4)$ and $(3,9)$).
\end{conjecture}
\begin{conjecture}[strict semiprime attenuation]
For every prime $\ell\ge5$, $I(N\bmod\ell;\{T(p),T(q)\})<H(T_\ell)$, with attenuation growing along primes for which $\ell-1$ has many divisors.
\end{conjecture}
\begin{conjecture}[real-subfield polynomial pinning]
The minimal polynomial of $2\cos(2\pi/n)$ over $\F_p$ factors into $\varphi(n)/(2t^+)$ irreducibles of degree $t^+$, the order of $p$ in $(\Z/n)^\times/\{\pm1\}$.
\end{conjecture}
Finally, one should quantify the failure of pinning, $H(T\mid c)>0$, for coset readouts of non-abelian Galois groups.

