"""Factor pattern of the cyclotomic polynomial Phi_n over F_p by distinct-degree
factorisation, cross-checked against the cycle type of multiplication by p on (Z/n)^x."""
from __future__ import annotations

import math
from typing import List

Poly = List[int]  # coefficients, lowest degree first


def trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def pmod(a: Poly, b: Poly, p: int) -> Poly:
    a = trim(a[:])
    inv = pow(b[-1], p - 2, p)
    while len(a) >= len(b):
        c, s = (a[-1] * inv) % p, len(a) - len(b)
        for i, bi in enumerate(b):
            a[s + i] = (a[s + i] - c * bi) % p
        trim(a)
    return a


def pmul(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    r = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            r[i + j] = (r[i + j] + ai * bj) % p
    return trim(r)


def pdivexact(a: Poly, b: Poly, p: int) -> Poly:
    a, q = a[:], [0] * (len(a) - len(b) + 1)
    inv = pow(b[-1], p - 2, p)
    while len(trim(a)) >= len(b):
        c, s = (a[-1] * inv) % p, len(a) - len(b)
        q[s] = c
        for i, bi in enumerate(b):
            a[s + i] = (a[s + i] - c * bi) % p
    return trim(q)


def pgcd(a: Poly, b: Poly, p: int) -> Poly:
    a, b = trim(a[:]), trim(b[:])
    while b:
        a, b = b, pmod(a, b, p)
    inv = pow(a[-1], p - 2, p)
    return [(x * inv) % p for x in a]


def cyclotomic(n: int) -> Poly:
    """Integer coefficients of Phi_n via x^n - 1 = prod_{d | n} Phi_d."""
    def div(a: List[int], b: List[int]) -> List[int]:
        a, q = a[:], [0] * (len(a) - len(b) + 1)
        for s in range(len(a) - len(b), -1, -1):
            c = a[s + len(b) - 1] // b[-1]
            q[s] = c
            for i, bi in enumerate(b):
                a[s + i] -= c * bi
        return q
    f = [-1] + [0] * (n - 1) + [1]
    for d in range(1, n):
        if n % d == 0:
            f = div(f, cyclotomic(d))
    return f


def ddf_pattern(f: Poly, p: int) -> List[int]:
    f, h, d, out = [c % p for c in f], [0, 1], 0, []
    while len(f) > 1:
        d += 1
        if 2 * d > len(f) - 1:
            out.append(len(f) - 1)
            break
        e, base, res = p, pmod(h, f, p), [1]
        while e:
            if e & 1:
                res = pmod(pmul(res, base, p), f, p)
            base, e = pmod(pmul(base, base, p), f, p), e >> 1
        h = res
        diff = h[:] + [0] * max(0, 2 - len(h))
        diff[1] = (diff[1] - 1) % p
        g = pgcd(f, trim(diff), p)
        if len(g) > 1:
            out += [d] * ((len(g) - 1) // d)
            f = pdivexact(f, g, p)
            h = pmod(h, f, p)
    return sorted(out)


def orbit_pattern(p: int, n: int) -> List[int]:
    U = [a for a in range(1, n) if math.gcd(a, n) == 1]
    seen, out = set(), []
    for a in U:
        if a in seen:
            continue
        x, L = a, 0
        while x not in seen:
            seen.add(x)
            x, L = (x * p) % n, L + 1
        out.append(L)
    return sorted(out)


if __name__ == "__main__":
    for n in (11, 12, 15, 21):
        f = cyclotomic(n)
        for p in (2, 3, 5, 7, 13, 23, 43):
            if n % p:
                assert ddf_pattern(f, p) == orbit_pattern(p, n)
        print(f"n={n}: DDF pattern == orbit pattern for all tested p; p=2 ->", ddf_pattern(f, 2) if n % 2 else "-")
